import{_ as i,C as l,o as n,c as r,j as s,a as o,E as d,a2 as h}from"./chunks/framework.DeW-aKVm.js";const y=JSON.parse('{"title":"Declarative K3s clusters with k3sctl","description":"k3sctl installs, upgrades, reconfigures, backs up, and resets K3s clusters from one YAML file over SSH.","frontmatter":{"title":"Declarative K3s clusters with k3sctl","description":"k3sctl installs, upgrades, reconfigures, backs up, and resets K3s clusters from one YAML file over SSH.","author":"vinaykumar","date":"2026-10-15T00:00:00.000Z","tags":["k3sctl","kubernetes","k3s"],"outline":"deep","editLink":false},"headers":[],"relativePath":"blog/declarative-k3s-clusters.md","filePath":"blog/declarative-k3s-clusters.md"}'),c={name:"blog/declarative-k3s-clusters.md"};function k(a,e,p,u,g,f){const t=l("AuthorCard");return n(),r("div",null,[e[0]||(e[0]=s("h1",{id:"declarative-k3s-clusters-with-k3sctl",tabindex:"-1"},[o("Declarative K3s clusters with k3sctl "),s("a",{class:"header-anchor",href:"#declarative-k3s-clusters-with-k3sctl","aria-label":'Permalink to "Declarative K3s clusters with k3sctl"'},"​")],-1)),d(t,{author:a.$frontmatter.author},null,8,["author"]),e[1]||(e[1]=h(`<p><code>k3sctl</code> manages the lifecycle of a K3s cluster from a single configuration file. It was created and inspired by <a href="https://github.com/k0sproject/k0sctl" target="_blank" rel="noreferrer">k0sctl</a>: you describe the hosts you want, and the tool does the work over SSH.</p><h2 id="the-file-is-the-desired-state" tabindex="-1">The file is the desired state <a class="header-anchor" href="#the-file-is-the-desired-state" aria-label="Permalink to &quot;The file is the desired state&quot;">​</a></h2><p>A k3sctl configuration is a <code>Cluster</code> document with an <code>apiVersion</code> of <code>k3sctl.k3sproject.io/v1beta1</code>. Each entry in <code>spec.hosts</code> has a <code>role</code> of <code>server</code> or <code>agent</code>, so the same file describes both the control plane and the workers.</p><p>Because the file is the desired state, the normal workflow is to edit it and run <code>apply</code> again. <code>apply</code> is idempotent: it only changes what drifted, and <code>--dry-run</code> shows the plan without touching the cluster.</p><h2 id="what-it-handles" tabindex="-1">What it handles <a class="header-anchor" href="#what-it-handles" aria-label="Permalink to &quot;What it handles&quot;">​</a></h2><ul><li>Installing and upgrading K3s binaries from GitHub releases, a URL, a local file, or an existing installation on the host.</li><li>Generating server and agent configuration plus systemd units.</li><li>Labels, taints, extra install flags, environment variables, and arbitrary file uploads.</li><li>Applying additional Kubernetes manifests bundled in the same file.</li><li>etcd snapshots with <code>backup</code>, member validation, and restore.</li><li>Fetching a ready-to-use admin kubeconfig with <code>kubeconfig</code>.</li></ul><p>Because the binary drives the hosts directly, servers and agents must be Linux and reachable over SSH with root or passwordless <code>sudo</code>.</p><h2 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">k3sctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --address</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10.0.0.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --agent-address</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10.0.0.2</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> k3sctl.yaml</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$EDITOR k3sctl.yaml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">k3sctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apply</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> k3sctl.yaml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">k3sctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kubeconfig</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kubeconfig.yaml</span></span></code></pre></div><p>Read the <a href="/docs/k3sctl/installation">installation guide</a> for release binaries and source builds, or the <a href="/docs/k3sctl/configuration">configuration reference</a> for every host and K3s option. <code>k3sctl</code> is Apache-2.0 licensed.</p>`,10))])}const F=i(c,[["render",k]]);export{y as __pageData,F as default};
